"        async function updateStatus() {
            try {
                const response = await fetch('/api/status');
                if (!response.ok) return;
                const data = await response.json();

                streamMount = data.icecast_mount;

                // Track server-side song changes to allow ear calibration
                const newTitle = data.current_track ? data.current_track.title : "";
                if (newTitle && newTitle !== currentSongTitle && newTitle !== "Sem reprodução") {
                    currentSongTitle = newTitle;
                    lastServerSongChangeTime = Date.now();
                }

                // Store Name header updates instantly to avoid lag
                const storeLabel = document.getElementById('store-name-label');
                if (storeLabel) storeLabel.textContent = data.store_name;

                data.fetched_at = Date.now();
                statusQueue.push(data);

                // If delay is 0, apply instantly and bypass queue
                if (delaySeconds === 0) {
                    statusQueue = [];
                    applyStatusData(data);
                }
            } catch (error) {
                console.error("Failed to poll status API:", error);
            }
        }"

