"package main

import (
	"context"
	"fmt"
	"imc-server/internal/database"
	"imc-server/internal/models"
	"imc-server/internal/utils"

	"github.com/google/uuid"
)

func main() {
	database.ConnectDatabase()
	defer database.Pool.Close()

	storeID := uuid.MustParse("ce275c7f-9b5a-4892-a802-efe432016721")
	var s models.Store
	ctx := context.Background()

	// Query from pgx pool
	row := database.Pool.QueryRow(ctx, "SELECT id, tenant_id, store_name, token, harbor_port, timezone, radio_type, store_number FROM stores WHERE id = $1", storeID)
	err := row.Scan(&s.ID, &s.TenantID, &s.StoreName, &s.Token, &s.HarborPort, &s.Timezone, &s.RadioType, &s.StoreNumber)
	if err != nil {
		fmt.Printf("Error fetching store: %v\n", err)
		return
	}

	err = utils.StartStoreDockerContainer(s)
	if err != nil {
		fmt.Printf("Error starting container: %v\n", err)
	} else {
		fmt.Println("Playout container successfully recreated and restarted!")
	}
}
"

